// ==UserScript==
// @name         Unreel: no Shorts, no Reels
// @namespace    unreel
// @version      1.0.0
// @description  Removes YouTube Shorts and Instagram Reels from the websites. A Short or Reel someone sends you opens as a normal video or post; the swipe feeds are gone.
// @match        *://*.youtube.com/*
// @match        *://*.instagram.com/*
// @run-at       document-start
// @inject-into  content
// @grant        none
// @noframes
// ==/UserScript==

// GENERATED by scripts/build-userscript.mjs from targets/safari/assets/content.{css,js}.
// Edit those files, then run `npm run build:userscript`.

(() => {
  // Hide the shelves, tabs and links that lead into Shorts and Reels.
  const css = "/*\n * Hides the entry points into Shorts and Reels. Selectors target both desktop (ytd-*) and the\n * mobile site Safari on iPhone actually gets (m.youtube.com, ytm-*). Like the Android view IDs,\n * these break when the sites redesign — keep them in one place and re-check after updates.\n */\n\n/* ---- YouTube: Shorts shelves, cards and nav ---- */\nytd-reel-shelf-renderer,\nytd-rich-shelf-renderer[is-shorts],\nytd-rich-section-renderer:has(ytd-rich-shelf-renderer[is-shorts]),\nytd-video-renderer:has(a[href^=\"/shorts/\"]),\nytd-grid-video-renderer:has(a[href^=\"/shorts/\"]),\nytd-guide-entry-renderer:has(a[title=\"Shorts\"]),\nytd-mini-guide-entry-renderer[aria-label=\"Shorts\"],\ngrid-shelf-view-model:has(a[href^=\"/shorts/\"]),\nytm-reel-shelf-renderer,\nytm-shorts-lockup-view-model,\nytm-shorts-lockup-view-model-v2,\nytm-rich-section-renderer:has(ytm-reel-shelf-renderer),\nytm-rich-section-renderer:has(a[href^=\"/shorts/\"]),\nytm-video-with-context-renderer:has(a[href^=\"/shorts/\"]),\nytm-pivot-bar-item-renderer:has(.pivot-shorts),\nyt-tab-shape[tab-title=\"Shorts\"] {\n  display: none !important;\n}\n\n/* ---- Instagram: Reels nav and profile tab ---- */\na[href=\"/reels/\"],\na[href$=\"/reels/\"][role=\"tab\"],\na[href^=\"/reels/\"] {\n  display: none !important;\n}\n";
  const addStyle = () => {
    if (document.getElementById('unreel-style')) return true;
    const root = document.head || document.documentElement;
    if (!root) return false; // At document-start the page may not have a root element yet.
    const style = document.createElement('style');
    style.id = 'unreel-style';
    style.textContent = css;
    root.appendChild(style);
    return true;
  };
  if (!addStyle()) {
    const observer = new MutationObserver(() => addStyle() && observer.disconnect());
    observer.observe(document, { childList: true, subtree: true });
  }
  // YouTube and Instagram rebuild parts of the page as you navigate; put the style back if it's dropped.
  setInterval(addStyle, 1000);
})();

/**
 * Unreel for Safari — removes Shorts and Reels from youtube.com and instagram.com.
 *
 * Two layers:
 *  1. rules.json (declarativeNetRequest) rewrites full page loads of /shorts/… and /reels/…
 *     before they render.
 *  2. This script handles in-page (SPA) navigation, which never hits the network as a page load,
 *     and content.css hides the shelves and nav entries that lead into the feeds.
 *
 * Policy mirrors the Android app: a single Short or Reel someone sent you opens as a normal
 * video/post (no swipe-to-next feed); the feeds themselves bounce back to the home page.
 */
(() => {
  const host = location.hostname;
  const isYouTube = /(^|\.)youtube\.com$/.test(host);
  const isInstagram = /(^|\.)instagram\.com$/.test(host);
  if (!isYouTube && !isInstagram) return;

  /** Returns the URL to go to instead, or null if this page is fine. */
  function rewrite(url) {
    const path = url.pathname;
    if (isYouTube) {
      const single = path.match(/^\/shorts\/([A-Za-z0-9_-]+)/);
      if (single) return `/watch?v=${single[1]}`;
      if (/^\/shorts\/?$/.test(path)) return '/';
      // Channel "Shorts" tabs: /@name/shorts
      const channelShorts = path.match(/^(\/@[^/]+)\/shorts\/?$/);
      if (channelShorts) return `${channelShorts[1]}/videos`;
    }
    if (isInstagram) {
      if (/^\/reels\/?$/.test(path)) return '/';
      const single = path.match(/^\/reels?\/([A-Za-z0-9_-]{8,})\/?$/);
      if (single) return `/p/${single[1]}/`;
      // Profile reels grid: /name/reels/
      const profileReels = path.match(/^(\/[^/]+)\/reels\/?$/);
      if (profileReels) return `${profileReels[1]}/`;
    }
    return null;
  }

  let lastHref = '';
  function check() {
    if (location.href === lastHref) return;
    lastHref = location.href;
    const target = rewrite(location);
    if (target && target !== location.pathname + location.search) {
      location.replace(target);
    }
  }

  // YouTube fires this after every in-app navigation; it's a DOM event, so it reaches the
  // isolated world content scripts run in.
  document.addEventListener('yt-navigate-finish', check);
  window.addEventListener('popstate', check);
  // Fallback for anything that changes history without an event we can see (Instagram).
  // Comparing one string twice a second is negligible.
  setInterval(check, 500);
  check();
})();
